/**
 * Bundles the migrations into a module the browser demo can load.
 *
 * The demo runs the real schema in WASM Postgres, so there is exactly one
 * source of truth for it: supabase/migrations. Re-run this after any migration
 * change (npm run demo:build) and commit the generated file.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = join(root, "supabase", "migrations");

const files = readdirSync(migrationsDir).filter((f) => f.endsWith(".sql")).sort();
const migrations = files.map((name) => ({
  name,
  sql: readFileSync(join(migrationsDir, name), "utf8"),
}));

const banner = `// GENERATED by scripts/build-demo.mjs -- do not edit.
// Source: supabase/migrations/ (${files.length} files)
// Regenerate with: npm run demo:build
`;

writeFileSync(
  join(root, "docs", "schema.js"),
  banner + "export const MIGRATIONS = " + JSON.stringify(migrations, null, 0) + ";\n",
  "utf8",
);

const bytes = migrations.reduce((n, m) => n + m.sql.length, 0);
console.log(`docs/schema.js — ${files.length} migrations, ${(bytes / 1024).toFixed(1)} KB`);
